import{c as t,Q as r,j as n,m as a}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Enhancing Retrieval-Augmented Generation: A Study of Best Practices","description":"","frontmatter":{"url":"https://arxiv.org/abs/2501.07391","title":"Enhancing Retrieval-Augmented Generation: A Study of Best Practices","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2501.07391,"authors":["Siran Li","Linus Stenzel","Carsten Eickhoff","Seyed Ali Bahrainian"],"pdf_path":"pdfs/2501.07391.pdf","published_date":"2025-01-13T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-01-13-rag-best-practices-acl2025-2501-07391.md","filePath":"research/papers/2025-01-13-rag-best-practices-acl2025-2501-07391.md","lastUpdated":1785909234000}'),i={name:"research/papers/2025-01-13-rag-best-practices-acl2025-2501-07391.md"};function o(s,e,l,d,c,g){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="enhancing-retrieval-augmented-generation-a-study-of-best-practices" tabindex="-1">Enhancing Retrieval-Augmented Generation: A Study of Best Practices <a class="header-anchor" href="#enhancing-retrieval-augmented-generation-a-study-of-best-practices" aria-label="Permalink to &quot;Enhancing Retrieval-Augmented Generation: A Study of Best Practices&quot;">​</a></h1><p><strong>Authors</strong>: Siran Li, Linus Stenzel, Carsten Eickhoff, Seyed Ali Bahrainian <strong>Affiliation</strong>: University of Tübingen <strong>Published</strong>: January 13, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2501.07391" target="_blank" rel="noreferrer">https://arxiv.org/abs/2501.07391</a><strong>arXiv ID</strong>: 2501.07391 <strong>Categories</strong>: cs.CL <strong>Code</strong>: <a href="https://github.com/ali-bahrainian/RAG_best_practices" target="_blank" rel="noreferrer">https://github.com/ali-bahrainian/RAG_best_practices</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Retrieval-Augmented Generation (RAG) systems have recently shown remarkable advancements by integrating retrieval mechanisms into language models, enhancing their ability to produce more accurate and contextually relevant responses. However, the influence of various components and configurations within RAG systems remains underexplored. A comprehensive understanding of these elements is essential for tailoring RAG systems to complex retrieval tasks and ensuring optimal performance across diverse applications. In this paper, we develop several advanced RAG system designs that incorporate query expansion, various novel retrieval strategies, and a novel Contrastive In-Context Learning RAG. Our study systematically investigates key factors, including language model size, prompt design, document chunk size, knowledge base size, retrieval stride, query expansion techniques, Contrastive In-Context Learning knowledge bases, multilingual knowledge bases, and Focus Mode retrieving relevant context at sentence-level. Through extensive experimentation, we provide a detailed analysis of how these factors influence response quality. Our findings offer actionable insights for developing RAG systems, striking a balance between contextual richness and retrieval-generation efficiency, thereby paving the way for more adaptable and high-performing RAG frameworks in diverse real-world scenarios. Implementation code is made publicly accessible.</p><hr><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><h3 id="_9-個研究問題-rq-與對應方法" tabindex="-1">9 個研究問題（RQ）與對應方法 <a class="header-anchor" href="#_9-個研究問題-rq-與對應方法" aria-label="Permalink to &quot;9 個研究問題（RQ）與對應方法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>RQ</th><th>問題</th><th>技術方法</th></tr></thead><tbody><tr><td>RQ1</td><td>LLM 大小如何影響 RAG 品質？</td><td>多規模 LM 消融實驗</td></tr><tr><td>RQ2</td><td>Prompt 設計的細微差異影響多大？</td><td>Prompt 變體系統性比較</td></tr><tr><td>RQ3</td><td>Document chunk size 的影響？</td><td>不同 chunk 大小消融</td></tr><tr><td>RQ4</td><td>Knowledge base 大小的影響？</td><td>KB 規模消融</td></tr><tr><td>RQ5</td><td>Retrieval stride 的影響？</td><td>stride 間距實驗</td></tr><tr><td>RQ6</td><td>Query expansion 是否改善精確度？</td><td>多種 expansion 技術比較</td></tr><tr><td>RQ7</td><td>Contrastive ICL demonstration 的影響？</td><td><strong>Contrastive In-Context Learning RAG</strong>（新方法）</td></tr><tr><td>RQ8</td><td>多語言 KB 的影響？</td><td>跨語言 KB 配置</td></tr><tr><td>RQ9</td><td>Focus Mode（sentence-level）是否提升？</td><td>句子級上下文檢索</td></tr></tbody></table><h3 id="新型方法貢獻" tabindex="-1">新型方法貢獻 <a class="header-anchor" href="#新型方法貢獻" aria-label="Permalink to &quot;新型方法貢獻&quot;">​</a></h3><p><strong>Contrastive In-Context Learning RAG</strong>：在 in-context examples 中同時包含正確示範與對比性錯誤案例，引導模型更精確區分 relevant vs. irrelevant 資訊。</p><p><strong>Focus Mode</strong>：從完整 document chunk 進一步提取句子級精確上下文，減少噪音、提升生成精確度，對應「contextual richness vs. retrieval-generation efficiency」的平衡。</p><p><strong>Query Expansion</strong>：在檢索前擴充 query 表示，提升 recall；本文系統性比較多種 expansion 策略。</p><hr><h2 id="關鍵數字" tabindex="-1">關鍵數字 <a class="header-anchor" href="#關鍵數字" aria-label="Permalink to &quot;關鍵數字&quot;">​</a></h2><p>論文為 University of Tübingen（Siran Li et al.）正式研究論文，系統性回答 9 個 RAG research questions（LLM 大小 / prompt 設計 / chunk size / KB 大小 / retrieval stride / query expansion / Contrastive ICL-RAG / 多語 KB / Focus Mode）。註：先前歸檔誤標「2 頁短版」，已親驗 PDF 首頁更正為完整論文。</p><p>已知的量化結論：</p><ul><li><strong>Prompt 設計影響顯著</strong>（RQ2）：細微的 prompt 變動可顯著影響 retrieval-generation 對齊度</li><li><strong>Chunk size 存在最優點</strong>（RQ3）：過小（資訊不足）與過大（噪音引入）均降低品質</li><li><strong>Query expansion 改善精確度</strong>（RQ6）：多種 expansion 技術均有正向效果，但效益依任務而異</li><li><strong>Focus Mode 有效</strong>（RQ9）：句子級精確檢索優於 full-chunk 在需要精確 grounding 的任務</li></ul><hr><h2 id="對-prompt-caching-management-engineering-的關聯" tabindex="-1">對 Prompt Caching / Management / Engineering 的關聯 <a class="header-anchor" href="#對-prompt-caching-management-engineering-的關聯" aria-label="Permalink to &quot;對 Prompt Caching / Management / Engineering 的關聯&quot;">​</a></h2><h3 id="prompt-caching" tabindex="-1">Prompt Caching <a class="header-anchor" href="#prompt-caching" aria-label="Permalink to &quot;Prompt Caching&quot;">​</a></h3><ul><li><strong>Retrieval Stride 與快取互動</strong>：較大的 retrieval stride（跳過更多段落）減少 prompt 長度，但可能降低召回；快取策略設計時應考慮 stride 對 prompt 長度穩定性的影響（stride 越大 → prompt 越短 → 快取前綴命中率越高）</li><li><strong>Chunk Size 對快取 prefix 的影響</strong>：Document chunk size 直接決定每次注入 context 的 token 量，進而影響是否超過 Anthropic 1,024 token 快取門檻；最佳 chunk size 應同時考慮 RAG 品質與快取可行性</li><li><strong>Focus Mode 對快取的價值</strong>：句子級 Focus Mode 縮短每次 context 長度 → prompt 結構更穩定 → prefix 快取命中率更高</li></ul><h3 id="prompt-management" tabindex="-1">Prompt Management <a class="header-anchor" href="#prompt-management" aria-label="Permalink to &quot;Prompt Management&quot;">​</a></h3><ul><li><strong>System Prompt + Retrieval Context 邊界</strong>：本文強調 prompt design（RQ2）對 RAG 對齊的重要性，prompt manager 應明確分離 system instruction（穩定，可快取）vs. retrieved context（動態，不快取）</li><li><strong>Contrastive ICL 需要精心管理 few-shot examples</strong>：正/負對比示範的 prompt 模板需版本控管，因為 examples 品質直接影響生成行為</li><li><strong>多語言 KB 管理</strong>（RQ8）：多語言配置引入 prompt 語言選擇問題——應在 system prompt 明確指定回應語言，避免模型根據 retrieved docs 語言決定輸出語言</li></ul><h3 id="prompt-engineering" tabindex="-1">Prompt Engineering <a class="header-anchor" href="#prompt-engineering" aria-label="Permalink to &quot;Prompt Engineering&quot;">​</a></h3><ul><li><strong>Prompt Design 細節至關重要</strong>（RQ2 主要發現）：即使語義等效的 prompt 措辭，對 RAG 的 retrieval-generation 對齊影響可能顯著，呼應 2601.22025 的核心論點（「更好」的通用 prompt 不一定更好）</li><li><strong>Contrastive ICL 設計模式</strong>：prompt engineer 可主動在 few-shot examples 中加入對比案例（「以下是錯誤做法」），明確引導模型邊界——這是可直接應用的 prompt 技巧</li><li><strong>RAG prompt 設計黃金準則</strong>：contextual richness（完整資訊）vs. retrieval-generation efficiency（token 精簡）的平衡，為 RAG prompt 設計提供可量化的優化方向</li></ul>',26)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
